    std::fs::write(src.join("Other.tsx"), format!("{gone}export function Other(props: {{ b: Gone }}) {{ return null; }}\\n"))
        .unwrap();
    std::fs::write(src.join("Plain.tsx"), "export function Plain(props: { c: string }) { return null; }\\n").unwrap();
    let session = WatchSession::new(options);
    let published = session.initialize();
    assert!(
        published.diagnostics.iter().any(|diagnostic| diagnostic.affects.len() >= 2),
        "the fixture needs a diagnostic shared by several components: {:#?}",
        published.diagnostics
    );

    let keys: Vec<String> = published.components.keys().cloned().collect();
    let batch = session.components(&keys);
    for (key, answer) in keys.iter().zip(batch) {
        // What a scan of every diagnostic gives: those that name the key, each narrowed to it.
        let expected: Vec<Diagnostic> = published
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.affects.iter().any(|affected| affected == key))
            .map(|diagnostic| Diagnostic { affects: vec![key.clone()], ..diagnostic.clone() })
            .collect();
        assert_eq!(answer.unwrap().diagnostics, expected, "{key} in a batch");
        assert_eq!(session.component(key).unwrap().diagnostics, expected, "{key} on its own");
    }
    assert!(session.component("Plain").unwrap().diagnostics.is_empty() || keys.len() == 3);
}
